//! Boards (M5, US-18..US-20, ADR-0007): create and list boards.
//!
//! Board ids are generated by the client (UUIDv7, so a board can be created offline) and scoped
//! to their owner on the server: retrying a create with the same id returns the same board, and
//! an id already used by anyone else is the same 404 as a missing board. Owner and role always
//! come from the session.

use axum::Json;
use axum::extract::State;
use axum::response::{IntoResponse, Response};
use boards::{BoardError, BoardSummary, NewBoard};
use http::StatusCode;
use platform::problem::{ApiError, ProblemDetails};
use platform::text::{FieldRules, TextError};
use registry::Kind;
use serde::{Deserialize, Serialize};
use time::OffsetDateTime;
use utoipa::ToSchema;
use uuid::Uuid;

use crate::access::{Caller, ValidJson};
use crate::state::AppState;

pub const TAG: &str = "boards";

/// Longest board title, in grapheme clusters (data-model.md `boards.title`).
pub const TITLE_MAX: usize = 60;

/// Body of `POST /v1/boards`.
#[derive(Debug, Deserialize, ToSchema)]
#[serde(deny_unknown_fields)]
pub struct CreateBoardRequest {
    /// Client-generated UUIDv7 (lets the app create boards offline).
    #[schema(format = "uuid")]
    pub id: String,
    /// 1..=60 grapheme clusters after sanitizing; filtered like every user-written name.
    pub title: String,
    /// Registry reference `{id, version, params?}` of kind `backdrop`; `null` = the default.
    #[schema(value_type = Option<Object>)]
    #[serde(default)]
    pub backdrop: Option<serde_json::Value>,
}

/// A board's metadata as the caller sees it.
#[derive(Debug, Serialize, ToSchema)]
pub struct BoardView {
    #[schema(format = "uuid")]
    pub id: String,
    pub title: String,
    /// Normalized registry reference, or `null` for the default backdrop.
    #[schema(value_type = Option<Object>)]
    pub backdrop: Option<serde_json::Value>,
    /// The caller's role: `owner` or `collaborator`.
    pub role: &'static str,
    /// Change cursor: bumped on every change to the board or its pins.
    pub version: i64,
    #[serde(with = "time::serde::rfc3339")]
    #[schema(value_type = String, format = DateTime)]
    pub created_at: OffsetDateTime,
    #[serde(with = "time::serde::rfc3339")]
    #[schema(value_type = String, format = DateTime)]
    pub updated_at: OffsetDateTime,
}

impl From<BoardSummary> for BoardView {
    fn from(board: BoardSummary) -> Self {
        Self {
            id: board.id.hyphenated().to_string(),
            title: board.title,
            backdrop: board.backdrop,
            role: board.role.as_str(),
            version: board.version,
            created_at: board.created_at,
            updated_at: board.updated_at,
        }
    }
}

#[derive(Debug, Serialize, ToSchema)]
pub struct BoardEnvelope {
    pub board: BoardView,
}

#[derive(Debug, Serialize, ToSchema)]
pub struct BoardList {
    /// Boards the caller owns or collaborates on, most recently changed first.
    pub items: Vec<BoardView>,
}

/// Maps domain errors; anything unexpected is a 500 without detail.
pub(crate) fn board_error(err: BoardError) -> ApiError {
    match err {
        BoardError::NotFound => ApiError::NotFound,
        BoardError::LimitReached => ApiError::BoardLimitReached,
        other => ApiError::internal(other),
    }
}

/// A client-generated board id: a UUID of version 7.
fn client_board_id(raw: &str) -> Result<Uuid, ApiError> {
    Uuid::try_parse(raw)
        .ok()
        .filter(|id| id.get_version_num() == 7)
        .ok_or_else(|| ApiError::Validation("id must be a UUIDv7".to_owned()))
}

/// A sanitized board title (1..=60 grapheme clusters, text filter applied).
pub(crate) fn board_title(state: &AppState, raw: &str) -> Result<String, ApiError> {
    let rules = FieldRules {
        min_graphemes: 1,
        max_graphemes: TITLE_MAX,
    };
    state
        .profile
        .text_filter
        .check(raw, rules)
        .map_err(|err| {
            if let TextError::Blocked { list } = &err {
                tracing::info!(event = "text_filter.blocked", field = "title", list = %list, "text refused");
            }
            ApiError::Validation(format!("title {err}"))
        })
}

/// A backdrop reference checked against the registry; `null` stays `null`.
pub(crate) fn backdrop(
    state: &AppState,
    raw: Option<&serde_json::Value>,
) -> Result<Option<serde_json::Value>, ApiError> {
    match raw {
        None | Some(serde_json::Value::Null) => Ok(None),
        Some(value) => state
            .registry
            .validate_reference(value, Kind::Backdrop)
            .map(Some)
            .map_err(|err| {
                tracing::info!(error = %err, "backdrop rejected");
                ApiError::UnknownRegistryId
            }),
    }
}

/// Create a board. Auth: ses.
///
/// The caller becomes its owner (at most 20 live boards, `boards.max_per_owner`). Retrying with
/// the same `id` returns the existing board with 200 (the id is the idempotency key); an `id`
/// used by another account, or by one of the caller's deleted boards, is 404.
#[utoipa::path(
    post,
    path = "/v1/boards",
    tag = TAG,
    operation_id = "createBoard",
    security(("bearer" = [])),
    request_body = CreateBoardRequest,
    responses(
        (status = CREATED, description = "Created.", body = BoardEnvelope),
        (status = OK, description = "Retry of a create: the caller's existing board with this id.", body = BoardEnvelope),
        (status = BAD_REQUEST, description = "VALIDATION_FAILED: bad id or title, unknown field.", body = ProblemDetails),
        (status = UNAUTHORIZED, description = "UNAUTHENTICATED, SESSION_EXPIRED or SESSION_REVOKED.", body = ProblemDetails),
        (status = FORBIDDEN, description = "ONBOARDING_INCOMPLETE or ACCOUNT_SUSPENDED.", body = ProblemDetails),
        (status = NOT_FOUND, description = "NOT_FOUND: the id is not available to the caller.", body = ProblemDetails),
        (status = CONFLICT, description = "BOARD_LIMIT_REACHED (AC-18.2).", body = ProblemDetails),
        (status = UNPROCESSABLE_ENTITY, description = "UNKNOWN_REGISTRY_ID: the backdrop is not a known backdrop.", body = ProblemDetails),
        (status = TOO_MANY_REQUESTS, description = "RATE_LIMITED.", body = ProblemDetails),
    )
)]
pub async fn create_board(
    State(state): State<AppState>,
    caller: Caller,
    body: ValidJson<CreateBoardRequest>,
) -> Result<Response, ApiError> {
    let request = body.0;
    let board = NewBoard {
        id: client_board_id(&request.id)?,
        owner: caller.0.account_id,
        title: board_title(&state, &request.title)?,
        backdrop: backdrop(&state, request.backdrop.as_ref())?,
    };
    let created = state.boards.create(&board).await.map_err(board_error)?;
    let status = if created.created {
        StatusCode::CREATED
    } else {
        StatusCode::OK
    };
    Ok((
        status,
        Json(BoardEnvelope {
            board: created.board.into(),
        }),
    )
        .into_response())
}

/// Boards I own or collaborate on. Auth: ses.
#[utoipa::path(
    get,
    path = "/v1/boards",
    tag = TAG,
    operation_id = "listBoards",
    security(("bearer" = [])),
    responses(
        (status = OK, description = "The caller's boards.", body = BoardList),
        (status = UNAUTHORIZED, description = "UNAUTHENTICATED, SESSION_EXPIRED or SESSION_REVOKED.", body = ProblemDetails),
        (status = FORBIDDEN, description = "ONBOARDING_INCOMPLETE or ACCOUNT_SUSPENDED.", body = ProblemDetails),
        (status = TOO_MANY_REQUESTS, description = "RATE_LIMITED.", body = ProblemDetails),
    )
)]
pub async fn list_boards(
    State(state): State<AppState>,
    caller: Caller,
) -> Result<Json<BoardList>, ApiError> {
    let boards = state
        .boards
        .list_for(caller.0.account_id)
        .await
        .map_err(board_error)?;
    Ok(Json(BoardList {
        items: boards.into_iter().map(BoardView::from).collect(),
    }))
}

/// A board id from the path: a malformed id is just another id that does not exist.
pub(crate) fn board_id(raw: &str) -> Result<Uuid, ApiError> {
    Uuid::try_parse(raw).map_err(|_| ApiError::NotFound)
}
